export const STICKER_MAP: Record<string, Sticker> = Object.fromEntries(STICKERS.map((s) => [s.id, s]));

function stickerRarity(effect: StickerEffect): Rarity {
  if (effect === "Gold") return "ultrarare";
  if (effect === "Holo") return "mythic";
  if (effect === "Foil" || effect === "Lenticular") return "legendary";
  return "epic";
}

/** Skin-shaped catalog adapter for Upgrade (and vault after a win). Wear is unused in UI. */
export function stickerAsSkin(sticker: Sticker): Skin {
  const rarity = stickerRarity(sticker.effect);
  return {
    id: sticker.id,
    name: sticker.name,
    weapon: "Sticker",
    rarity,
    wear: "fn",
    price: sticker.price,
    stattrak: false,
    colors: [...RARITY_COLORS[rarity]],
    image: sticker.image,
    collection: sticker.tournament,
  };
}

export const STICKER_SKINS: Skin[] = STICKERS.map(stickerAsSkin);
export const STICKER_SKIN_MAP: Record<string, Skin> = Object.fromEntries(STICKER_SKINS.map((s) => [s.id, s]));
